<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Activity, BellRing, ChevronDown, ChevronUp, Clock3, Mail, Search, ShieldCheck, Trash2 } from '@lucide/vue'
import { LocalApi, type EmailSettings, type Friend, type NotificationDelivery, type PresenceWatchRule } from './api'
const props=defineProps<{friends:Friend[]}>();const api=new LocalApi();const query=ref('');const watches=ref<PresenceWatchRule[]>([]);const deliveries=ref<NotificationDelivery[]>([]);const email=ref<EmailSettings>({enabled:false,host:'',port:587,security:'starttls',username:'',from:'',to:'',configured:false,password:''});const busy=ref('');const message=ref('');const expanded=ref<Set<string>>(new Set())
const watchedIDs=computed(()=>new Set(watches.value.map(x=>x.userId)));const candidates=computed(()=>props.friends.filter(x=>!watchedIDs.value.has(x.id)&&(!query.value||`${x.displayName} ${x.id}`.toLowerCase().includes(query.value.toLowerCase()))).slice(0,120));const health=computed(()=>{const recent=deliveries.value.filter(x=>Date.now()-new Date(x.observedAt).getTime()<86400000);return{sent:recent.filter(x=>x.status==='sent').length,failed:recent.filter(x=>x.status==='failed').length,queued:recent.filter(x=>x.status==='queued').length,suppressed:recent.filter(x=>x.status==='suppressed').length,last:deliveries.value[0]?.observedAt}})
async function load(){await api.bootstrap();[watches.value,email.value,deliveries.value]=await Promise.all([api.presenceWatches(),api.presenceEmail(),api.presenceDeliveries()])}
function defaults(friend:Friend):Omit<PresenceWatchRule,'updatedAt'>{return{userId:friend.id,displayName:friend.displayName,notifyOnline:true,notifyOffline:true,notifyLocation:false,notifyJoinable:true,desktopEnabled:true,emailEnabled:false,minOnlineSeconds:30,quietStart:'23:00',quietEnd:'08:00',emailMode:'instant',digestHour:9,currentState:friend.online?'online':'offline'}}
async function add(friend:Friend){busy.value=friend.id;try{watches.value.push(await api.savePresenceWatch(defaults(friend)))}finally{busy.value=''}}
async function save(item:PresenceWatchRule){busy.value=item.userId;message.value='';try{const saved=await api.savePresenceWatch({...item});watches.value=watches.value.map(x=>x.userId===saved.userId?saved:x);message.value=`已保存 ${saved.displayName} 的提醒规则`}catch(e){message.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=''}}
async function remove(item:PresenceWatchRule){busy.value=item.userId;try{await api.deletePresenceWatch(item.userId);watches.value=watches.value.filter(x=>x.userId!==item.userId)}finally{busy.value=''}}
async function saveEmail(test=false){busy.value='email';message.value='';try{email.value=await api.savePresenceEmail(email.value);email.value.password='';if(test){await api.testPresenceEmail();message.value='测试邮件已发送'}else message.value='邮件配置已安全保存'}catch(e){message.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=''}}
function toggle(id:string){const next=new Set(expanded.value);next.has(id)?next.delete(id):next.add(id);expanded.value=next}function formatTime(value?:string){if(!value)return'暂无投递';const date=new Date(value);return Number.isNaN(date.getTime())?'暂无投递':date.toLocaleString()}onMounted(()=>load().catch(e=>message.value=e instanceof Error?e.message:'加载失败'))
</script>
<template><section class="presence-view wide-view">
<header class="presence-hero"><div><span class="panel-kicker">特别关心 2.0</span><h2><BellRing :size="21"/>好友动态提醒</h2><p>防抖、免打扰、位置变化与邮件汇总都在本机执行。</p></div><label class="friend-search"><Search :size="16"/><input v-model="query" placeholder="搜索好友或 ID"/></label></header>
<div class="health-grid"><article><Activity :size="17"/><span><b>{{ health.sent }}</b>24 小时成功</span></article><article :class="{danger:health.failed}"><ShieldCheck :size="17"/><span><b>{{ health.failed }}</b>失败</span></article><article><Clock3 :size="17"/><span><b>{{ health.queued }}</b>等待汇总</span></article><article><BellRing :size="17"/><span><b>{{ health.suppressed }}</b>免打扰拦截</span></article><small>最后活动：{{ formatTime(health.last) }}</small></div>
<div class="presence-columns"><article class="presence-card"><header><div><h3>提醒规则</h3><span>{{ watches.length }} 位好友</span></div><small>点击好友展开独立规则</small></header><div v-if="watches.length" class="watch-list"><section v-for="item in watches" :key="item.userId" class="watch-row" :class="{expanded:expanded.has(item.userId)}"><button class="watch-summary" @click="toggle(item.userId)"><i></i><strong>{{ item.displayName }}</strong><small>{{ item.minOnlineSeconds?`上线稳定 ${item.minOnlineSeconds} 秒后提醒`:'立即提醒' }}</small><ChevronUp v-if="expanded.has(item.userId)" :size="15"/><ChevronDown v-else :size="15"/></button><div v-if="expanded.has(item.userId)" class="rule-editor"><fieldset><legend>触发事件</legend><label><input v-model="item.notifyOnline" type="checkbox"/>上线</label><label><input v-model="item.notifyOffline" type="checkbox"/>下线</label><label><input v-model="item.notifyLocation" type="checkbox"/>世界变化</label><label><input v-model="item.notifyJoinable" type="checkbox"/>位置变为可加入</label></fieldset><fieldset><legend>投递渠道</legend><label><input v-model="item.desktopEnabled" type="checkbox"/>托盘</label><label><input v-model="item.emailEnabled" type="checkbox"/>邮件</label><select v-model="item.emailMode"><option value="instant">即时邮件</option><option value="digest">每日汇总</option></select><label v-if="item.emailMode==='digest'">{{ item.digestHour }} 时<input v-model.number="item.digestHour" min="0" max="23" type="range"/></label></fieldset><fieldset><legend>节流与免打扰</legend><label>上线稳定<input v-model.number="item.minOnlineSeconds" min="0" max="3600" step="10" type="number"/>秒</label><label>从<input v-model="item.quietStart" type="time"/></label><label>到<input v-model="item.quietEnd" type="time"/></label></fieldset><footer><span>{{ busy===item.userId?'保存中':message }}</span><button class="remove" @click="remove(item)"><Trash2 :size="14"/>取消</button><button :disabled="busy===item.userId" @click="save(item)">保存规则</button></footer></div></section></div><div v-else class="empty-compact">从右侧添加需要特别关心的好友。</div></article>
<article class="presence-card"><header><div><h3>添加好友</h3><span>{{ candidates.length }} 个结果</span></div></header><div class="candidate-list"><button v-for="friend in candidates" :key="friend.id" :disabled="busy===friend.id" @click="add(friend)"><i :class="{online:friend.online}"/><strong>{{ friend.displayName }}</strong><small>{{ friend.online?'在线':'离线' }}</small></button><p v-if="!candidates.length">没有匹配的好友</p></div></article></div>
<article class="presence-card"><header><div><h3><Mail :size="17"/>邮件通道</h3><span>{{ email.configured?'授权码已由 Windows 加密保存':'尚未配置' }}</span></div><small>收件人与发件人必须一致，防止被用于向他人群发。</small></header><div class="email-grid"><label>SMTP<input v-model="email.host"/></label><label>端口<input v-model.number="email.port" type="number"/></label><label>加密<select v-model="email.security"><option value="starttls">STARTTLS</option><option value="tls">TLS</option></select></label><label>账号<input v-model="email.username"/></label><label>发件邮箱<input v-model="email.from" type="email"/></label><label>接收邮箱<input v-model="email.to" type="email"/></label><label>授权码<input v-model="email.password" type="password" :placeholder="email.configured?'留空保持现有授权码':'SMTP 授权码'"/></label></div><div class="email-actions"><label><input v-model="email.enabled" type="checkbox"/>启用邮件</label><span>{{ message }}</span><button @click="saveEmail(false)">保存</button><button @click="saveEmail(true)">保存并测试</button></div></article>
<article class="presence-card"><header><div><h3>投递记录</h3><span>最近 {{ deliveries.length }} 条</span></div><small>失败、排队和免打扰都有明确原因</small></header><div class="delivery-list"><span v-for="item in deliveries.slice(0,30)" :key="item.id"><b :data-status="item.status">{{ item.status==='sent'?'成功':item.status==='queued'?'汇总中':item.status==='suppressed'?'已静默':'失败' }}</b><strong>{{ item.message }}</strong><em>{{ item.channel==='email'?'邮件':'托盘' }}</em><small>{{ formatTime(item.observedAt) }}<i v-if="item.error"> · {{ item.error }}</i></small></span><p v-if="!deliveries.length" class="empty-compact">暂无投递记录</p></div></article>
</section></template>
<style scoped>
.presence-view{display:grid;gap:12px}.presence-hero,.presence-card>header,.presence-card>header>div,.presence-hero h2,.email-actions{display:flex;align-items:center}.presence-hero{justify-content:space-between}.presence-hero h2{gap:8px;margin:3px 0;font-size:22px}.presence-hero p{margin:0;color:var(--muted);font-size:11px}.friend-search{width:min(390px,42%);display:flex;align-items:center;gap:8px;padding:9px 11px;border:1px solid var(--line);border-radius:7px;background:var(--surface)}input,select{min-width:0;color:var(--ink)}.friend-search input{width:100%;border:0;outline:0;background:transparent}.health-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr)) auto;border:1px solid var(--line);border-radius:8px;background:var(--surface);overflow:hidden}.health-grid article{display:flex;align-items:center;gap:9px;padding:12px;border-right:1px solid var(--line);color:var(--muted)}.health-grid b{margin-right:5px;color:var(--ink);font-size:18px}.health-grid .danger,.health-grid .danger b{color:var(--danger)}.health-grid>small{display:flex;align-items:center;padding:0 13px;color:var(--muted);font-size:9px}.presence-columns{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(280px,.55fr);gap:12px}.presence-card{min-width:0;padding:15px;border:1px solid var(--line);border-radius:8px;background:var(--surface)}.presence-card>header{justify-content:space-between;margin-bottom:11px}.presence-card>header>div{gap:8px}.presence-card h3{display:flex;align-items:center;gap:6px;margin:0;font-size:14px}.presence-card header span,.presence-card header small{color:var(--muted);font-size:9px}.watch-list,.candidate-list,.delivery-list{display:grid;gap:6px;max-height:460px;overflow:auto}.watch-row{border:1px solid var(--line);border-radius:7px;background:var(--surface-muted);overflow:hidden}.watch-row.expanded{border-color:var(--accent)}.watch-summary{width:100%;display:grid;grid-template-columns:8px minmax(120px,1fr) auto 18px;align-items:center;gap:9px;padding:10px;border:0;background:transparent;color:var(--ink);text-align:left}.watch-summary i,.candidate-list button>i{width:7px;height:7px;border-radius:50%;background:var(--accent)}.watch-summary strong{font-size:12px}.watch-summary small{color:var(--muted);font-size:9px}.rule-editor{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:10px;border-top:1px solid var(--line);background:var(--surface)}fieldset{display:flex;align-items:center;align-content:flex-start;flex-wrap:wrap;gap:8px;margin:0;padding:9px;border:1px solid var(--line);border-radius:6px}legend{padding:0 4px;color:var(--muted);font-size:9px}fieldset label{display:flex;align-items:center;gap:4px;font-size:10px}fieldset select,fieldset input[type=time],fieldset input[type=number]{height:28px;padding:0 6px;border:1px solid var(--line);border-radius:5px;background:var(--surface-muted);font-size:9px}fieldset input[type=number]{width:62px}.rule-editor footer{grid-column:1/-1;display:flex;align-items:center;justify-content:flex-end;gap:7px}.rule-editor footer span{margin-right:auto;color:var(--muted);font-size:9px}.rule-editor footer button,.email-actions button{display:inline-flex;align-items:center;gap:4px;padding:7px 9px;border:1px solid var(--line-strong);border-radius:5px;background:var(--surface-muted);color:var(--ink);font-size:10px}.rule-editor footer .remove{color:var(--danger)}.candidate-list button{display:grid;grid-template-columns:9px 1fr auto;align-items:center;gap:8px;padding:10px;border:0;border-radius:6px;color:var(--ink);background:var(--surface-muted);text-align:left}.candidate-list button>i{background:var(--muted)}.candidate-list button>i.online{background:var(--success)}.candidate-list strong{font-size:11px}.candidate-list small{color:var(--muted);font-size:9px}.email-grid{display:grid;grid-template-columns:2fr .7fr 1fr 1.5fr;gap:9px}.email-grid label{display:grid;gap:5px;color:var(--muted);font-size:10px}.email-grid input,.email-grid select{height:34px;padding:0 8px;border:1px solid var(--line);border-radius:6px;background:var(--surface-muted)}.email-actions{justify-content:flex-end;gap:9px;margin-top:10px}.email-actions>label{margin-right:auto}.email-actions span{color:var(--muted);font-size:9px}.delivery-list>span{display:grid;grid-template-columns:52px minmax(0,1fr) 44px;align-items:center;gap:8px;padding:7px 2px;border-bottom:1px solid var(--line)}.delivery-list b{padding:3px 5px;border-radius:4px;background:var(--success-soft);color:var(--success);font-size:9px;text-align:center}.delivery-list b[data-status=failed]{background:var(--danger-soft);color:var(--danger)}.delivery-list b[data-status=queued],.delivery-list b[data-status=suppressed]{background:var(--warning-soft);color:var(--warning)}.delivery-list strong{font-size:10px}.delivery-list em{color:var(--muted);font-size:9px;font-style:normal}.delivery-list small{grid-column:2/-1;color:var(--muted);font-size:8px}.delivery-list i{color:var(--danger);font-style:normal}.empty-compact,.candidate-list>p{padding:16px;color:var(--muted);text-align:center;font-size:10px}@media(max-width:1050px){.presence-columns{grid-template-columns:1fr}.rule-editor{grid-template-columns:1fr 1fr}.email-grid{grid-template-columns:1fr 1fr}.health-grid{grid-template-columns:1fr 1fr}.health-grid>small{min-height:36px}}@media(max-width:680px){.presence-hero{align-items:stretch;flex-direction:column;gap:10px}.friend-search{width:auto}.rule-editor,.email-grid{grid-template-columns:1fr}.watch-summary{grid-template-columns:8px 1fr 18px}.watch-summary small{display:none}.health-grid>small{grid-column:1/-1}}
</style>
